/**
 * 📐 ALUCAD OS — AEGIS SPATIAL GROUNDING & ASSEMBLY HEALER
 * 
 * Automatically analyzes raw multi-part CAD assemblies generated by LLMs,
 * eliminates floating surfaces, aligns grounded supports to Y=0 floor level,
 * snaps surface accessories (monitors, tools) onto tabletops, and guarantees
 * physical CAD realism even when standard lightweight APIs produce slight coordinate errors.
 */

import { type DesignPart } from '@/design-studio/designStore';

export function groundAndAlignAssembly(rawParts: DesignPart[]): DesignPart[] {
  if (!rawParts || rawParts.length === 0) return rawParts;

  const parts = rawParts.map((p) => ({
    ...p,
    position: { ...p.position },
    params: { ...p.params },
  }));

  // 1. Initial check: If entire assembly is sunken underground (Y < -1) or extremely in space (> 1500), shift flush
  let initialLowestY = Infinity;
  for (const p of parts) {
    const h = Number(p.params.height || p.params.length || p.params.diameter || 20);
    const bottomY = p.position.y - h / 2;
    if (bottomY < initialLowestY) {
      initialLowestY = bottomY;
    }
  }

  if (Number.isFinite(initialLowestY) && (initialLowestY < -1 || initialLowestY > 1500)) {
    const shiftY = -initialLowestY;
    for (const p of parts) {
      p.position.y += shiftY;
    }
  }

  // 2. Identify Horizontal Work Surfaces (Tabletops, Desks, Slabs)
  const surfaces: Array<{
    part: DesignPart;
    minX: number;
    maxX: number;
    minZ: number;
    maxZ: number;
    topY: number;
    bottomY: number;
  }> = [];

  for (const p of parts) {
    const w = Number(p.params.width || p.params.diameter || 100);
    const d = Number(p.params.depth || p.params.length || 100);
    const h = Number(p.params.height || 25);

    // If it's a wide, relatively thin slab (typical tabletop or platform)
    if (w >= 350 && d >= 250 && h <= 80 && p.position.y > 300) {
      surfaces.push({
        part: p,
        minX: p.position.x - w / 2,
        maxX: p.position.x + w / 2,
        minZ: p.position.z - d / 2,
        maxZ: p.position.z + d / 2,
        topY: p.position.y + h / 2,
        bottomY: p.position.y - h / 2,
      });
    }
  }

  // 3. Check each surface: Does it have support touching the floor (Y ≈ 0)?
  const generatedLegs: DesignPart[] = [];

  for (const s of surfaces) {
    const hasFloorSupport = parts.some((p) => {
      if (p.id === s.part.id) return false;
      const ph = Number(p.params.height || p.params.length || 50);
      const pBottom = p.position.y - ph / 2;
      const pTop = p.position.y + ph / 2;
      const withinX = Math.abs(p.position.x - s.part.position.x) < (s.maxX - s.minX) / 1.5;
      const withinZ = Math.abs(p.position.z - s.part.position.z) < (s.maxZ - s.minZ) / 1.5;

      return withinX && withinZ && pBottom <= 30 && pTop >= s.bottomY - 50;
    });

    // If the desk/tabletop is floating in mid-air with no floor legs/panels (like in the user's screenshot),
    // heal it by attaching realistic ground support panels to Y=0!
    if (!hasFloorSupport && s.bottomY > 350) {
      const legHeight = s.bottomY;
      const legWidth = Math.min(25, (s.maxX - s.minX) * 0.05);
      const legDepth = Math.max(100, (s.maxZ - s.minZ) * 0.85);

      // Outer side panel leg
      generatedLegs.push({
        id: `auto-leg-${s.part.id}-1`,
        name: `${s.part.name} Taşıyıcı Yan Ayak`,
        kind: 'box',
        params: { width: legWidth, height: legHeight, depth: legDepth },
        position: {
          x: s.maxX - legWidth / 2,
          y: legHeight / 2,
          z: s.part.position.z,
        },
        rotation: { x: 0, y: 0, z: 0 },
        scale: { x: 1, y: 1, z: 1 },
        color: s.part.color || '#d4b896',
        visible: true,
        locked: false,
        parentId: s.part.id,
      });
    }
  }

  // 4. Snap Small Surface Objects (Monitors, Keyboards, Tools) onto their Tabletop
  for (const p of parts) {
    const w = Number(p.params.width || p.params.diameter || 50);
    const d = Number(p.params.depth || p.params.length || 50);
    const h = Number(p.params.height || 50);

    // Guard: ignore floor-grounded elements (legs, pedestals, under-desk towers, chairs, cabinets)
    const lowerName = (p.name || '').toLowerCase();
    const isFloorGrounded =
      p.position.y - h / 2 <= 50 ||
      lowerName.includes('ayak') ||
      lowerName.includes('keson') ||
      lowerName.includes('dolap') ||
      lowerName.includes('sandalye') ||
      lowerName.includes('kasa') ||
      lowerName.includes('base') ||
      lowerName.includes('zemin') ||
      lowerName.includes('floor');

    // If it's a small tabletop accessory (like monitor, keyboard, mouse)
    if (!isFloorGrounded && w <= 650 && d <= 450 && h <= 500) {
      // Find supporting surface directly below it
      const supportingSurface = surfaces.find(
        (s) =>
          p.position.x >= s.minX - 50 &&
          p.position.x <= s.maxX + 50 &&
          p.position.z >= s.minZ - 50 &&
          p.position.z <= s.maxZ + 50 &&
          p.position.y > s.topY - 100 &&
          p.position.y < s.topY + 500
      );

      if (supportingSurface) {
        // Snap bottom of accessory to rest exactly on top of desk surface
        p.position.y = supportingSurface.topY + h / 2;
      }
    }
  }

  // 5. Final Floor Leveling: Ensure floating assemblies/machines without legs sit flush at Y = 0
  const isAirborne = parts.some((p) => {
    const n = (p.name || '').toLowerCase();
    return (
      n.includes('propeller') ||
      n.includes('pervane') ||
      n.includes('drone') ||
      n.includes('quadcopter') ||
      n.includes('uav') ||
      n.includes('satellite')
    );
  });

  if (!isAirborne) {
    let finalLowestY = Infinity;
    const allParts = [...parts, ...generatedLegs];
    for (const p of allParts) {
      const h = Number(p.params.height || p.params.length || p.params.diameter || 20);
      const bottomY = p.position.y - h / 2;
      if (bottomY < finalLowestY) {
        finalLowestY = bottomY;
      }
    }

    if (Number.isFinite(finalLowestY) && (finalLowestY > 1.0 || finalLowestY < -1.0)) {
      const shiftY = -finalLowestY;
      for (const p of parts) {
        p.position.y = Math.round((p.position.y + shiftY) * 10) / 10;
      }
      for (const p of generatedLegs) {
        p.position.y = Math.round((p.position.y + shiftY) * 10) / 10;
      }
    }
  }

  return [...parts, ...generatedLegs];
}
